  1→/**
  2→ * Dispute Review — precedents: human reviewers' decisions, kept so the AI Judge
  3→ * can calibrate to the team's standards (few-shot examples in its prompt).
  4→ *
  5→ * Stored in a JSON file (PRECEDENTS_FILE) so they survive restarts, unlike the
  6→ * in-memory cases. Only decisions the reviewer marked "use as precedent" are kept.
  7→ */
  8→
  9→import fs from 'fs';
 10→import path from 'path';
 11→import { z } from 'zod';
 12→import { env } from '../../config/env';
 13→import { createLogger } from '../../config/logger';
 14→import type { DisputeCase, DisputeType, HumanOverride } from './types';
 15→
 16→const logger = createLogger('Precedents');
 17→
 18→const recommendation = z.enum(['driver', 'passenger', 'shared', 'inconclusive']);
 19→
 20→const precedentSchema = z.object({
 21→  caseNumber: z.string(),
 22→  type: z.enum(['route_deviation', 'fare_dispute', 'no_show_charge', 'property_damage', 'safety_accident']),
 23→  title: z.string(),
 24→  facts: z.string(),
 25→  aiRecommendation: recommendation.optional(),
 26→  aiConfidence: z.number().optional(),
 27→  humanRecommendation: recommendation,
 28→  reason: z.string(),
 29→  decidedBy: z.string().optional(),
 30→  decidedAt: z.string(),
 31→});
 32→
 33→export type Precedent = z.infer<typeof precedentSchema>;
 34→
 35→// Keeps each example short so a few of them fit the Judge's prompt
 36→const MAX_FACTS_CHARS = 900;
 37→
 38→const clip = (text: string, max: number) => (text.length > max ? `${text.slice(0, max)}…` : text);
 39→
 40→/** What the case was about, in a few sentences, for the Judge to compare against. */
 41→function caseFacts(c: DisputeCase): string {
 42→  const parts: string[] = [];
 43→  if (c.dataset) parts.push(`Complaint: ${clip(c.dataset.dispute_ticket.description, 400)}`);
 44→  else {
 45→    if (c.driver.statement) parts.push(`Driver says: ${clip(c.driver.statement, 300)}`);
 46→    if (c.passenger.statement) parts.push(`Rider says: ${clip(c.passenger.statement, 300)}`);
 47→  }
 48→  if (c.review?.mode !== 'fallback' && c.review?.summary) parts.push(`AI summary: ${clip(c.review.summary, 400)}`);
 49→  return clip(parts.join('\n'), MAX_FACTS_CHARS);
 50→}
 51→
 52→export function precedentFromCase(c: DisputeCase, decision: HumanOverride): Precedent {
 53→  const aiRan = c.review && c.review.mode !== 'fallback';
 54→  return {
 55→    caseNumber: c.caseNumber,
 56→    type: c.type,
 57→    title: c.title,
 58→    facts: caseFacts(c),
 59→    aiRecommendation: aiRan ? c.review!.recommendation : undefined,
 60→    aiConfidence: aiRan ? c.review!.confidenceScore : undefined,
 61→    humanRecommendation: decision.recommendation,
 62→    reason: decision.reason,
 63→    decidedBy: decision.decidedBy,
 64→    decidedAt: decision.decidedAt,
 65→  };
 66→}
 67→
 68→let cache: Precedent[] | null = null;
 69→
 70→function filePath(): string {
 71→  return path.resolve(env.PRECEDENTS_FILE);
 72→}
 73→
 74→function load(): Precedent[] {
 75→  if (cache) return cache;
 76→  try {
 77→    const parsed = z.array(z.unknown()).parse(JSON.parse(fs.readFileSync(filePath(), 'utf8')));
 78→    // Skip entries that were edited by hand into an invalid shape rather than losing them all
 79→    cache = parsed.flatMap((p) => {
 80→      const result = precedentSchema.safeParse(p);
 81→      return result.success ? [result.data] : [];
 82→    });
 83→  } catch (err) {
 84→    if ((err as NodeJS.ErrnoException).code !== 'ENOENT') {
 85→      logger.warn({ err: err instanceof Error ? err.message : err, file: filePath() }, 'Could not read precedents; starting empty');
 86→    }
 87→    cache = [];
 88→  }
 89→  return cache;
 90→}
 91→
 92→function save(list: Precedent[]): void {
 93→  const file = filePath();
 94→  fs.mkdirSync(path.dirname(file), { recursive: true });
 95→  // Write then rename, so a crash mid-write never leaves a half-written file
 96→  const tmp = `${file}.tmp`;
 97→  fs.writeFileSync(tmp, JSON.stringify(list, null, 2));
 98→  fs.renameSync(tmp, file);
 99→  cache = list;
100→}
101→
102→export const precedentStore = {
103→  /** Newest first */
104→  list(): Precedent[] {
105→    return [...load()].sort((a, b) => b.decidedAt.localeCompare(a.decidedAt));
106→  },
107→
108→  /** One precedent per case; a newer decision on the same case replaces it. */
109→  upsert(p: Precedent): void {
110→    save([...load().filter((x) => x.caseNumber !== p.caseNumber), p]);
111→  },
112→
113→  remove(caseNumber: string): boolean {
114→    const list = load();
115→    const next = list.filter((x) => x.caseNumber !== caseNumber);
116→    if (next.length === list.length) return false;
117→    save(next);
118→    return true;
119→  },
120→
121→  /**
122→   * Examples for the Judge: same dispute type only (another type's ruling could
123→   * mislead), newest first, never the case under review (its own earlier decision
124→   * must not decide it again).
125→   */
126→  select(type: DisputeType, excludeCaseNumber: string, limit = env.PRECEDENT_EXAMPLES): Precedent[] {
127→    return this.list()
128→      .filter((p) => p.type === type && p.caseNumber !== excludeCaseNumber)
129→      .slice(0, limit);
130→  },
131→};
132→

