 27→const schemaSql = (dim) => `
 28→CREATE EXTENSION IF NOT EXISTS vector;
 29→
 30→CREATE TABLE IF NOT EXISTS documents (
 31→  id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
 32→  case_id           TEXT,
 33→  source_type       TEXT NOT NULL CHECK (source_type IN ('pdf', 'text', 'image', 'company_record')),
 34→  title             TEXT NOT NULL,
 35→  original_filename TEXT,
 36→  mime_type         TEXT,
 37→  storage_path      TEXT,
 38→  size_bytes        INTEGER,
 39→  sha256            TEXT NOT NULL,
 40→  extracted_text    TEXT NOT NULL DEFAULT '',
 41→  metadata          JSONB NOT NULL DEFAULT '{}'::jsonb,
 42→  status            TEXT NOT NULL DEFAULT 'processing' CHECK (status IN ('processing', 'ready', 'failed')),
 43→  error             TEXT,
 44→  chunk_count       INTEGER NOT NULL DEFAULT 0,
 45→  created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
 46→  updated_at        TIMESTAMPTZ NOT NULL DEFAULT now()
 47→);
 48→
 49→-- The same file uploaded twice to the same case is stored once
 50→CREATE UNIQUE INDEX IF NOT EXISTS documents_sha256_case_uq
 51→  ON documents (sha256, COALESCE(case_id, ''));
 52→CREATE INDEX IF NOT EXISTS documents_case_idx ON documents (case_id);
 53→
 54→CREATE TABLE IF NOT EXISTS document_chunks (
 55→  id           BIGSERIAL PRIMARY KEY,
 56→  document_id  UUID NOT NULL REFERENCES documents(id) ON DELETE CASCADE,
 57→  case_id      TEXT,
 58→  source_type  TEXT NOT NULL,
 59→  chunk_index  INTEGER NOT NULL,
 60→  page         INTEGER,
 61→  content      TEXT NOT NULL,
 62→  embedding    vector(${dim}) NOT NULL,
 63→  created_at   TIMESTAMPTZ NOT NULL DEFAULT now()
 64→);
 65→
 66→CREATE INDEX IF NOT EXISTS document_chunks_embedding_hnsw
 67→  ON document_chunks USING hnsw (embedding vector_cosine_ops);
 68→CREATE INDEX IF NOT EXISTS document_chunks_case_idx ON document_chunks (case_id);
 69→CREATE INDEX IF NOT EXISTS document_chunks_document_idx ON document_chunks (document_id);
