/**
 * Module-resolution shim: redirects require("pg") to a local mock
 * so the server starts without a PostgreSQL driver installed.
 *
 * The real pg module is only used by the knowledge-base feature
 * (config/database.ts), which gracefully degrades when the DB is
 * unreachable. This mock makes pool.connect() throw ECONNREFUSED,
 * which index.ts catches and logs as a warning.
 */
const Module = require('module');
const path = require('path');

const mockPath = path.resolve(__dirname, 'pg-mock.js');
const originalResolve = Module._resolveFilename;

Module._resolveFilename = function (request, parent, isMain, options) {
  if (request === 'pg') {
    return mockPath;
  }
  return originalResolve.apply(this, arguments);
};

/**
 * Mock pg module for deployment environments without PostgreSQL.
 *
 * The real pg.Pool tries to connect to a database; this mock throws
 * ECONNREFUSED on connect(), which index.ts catches and logs as a
 * warning. The dispute-review features work without the knowledge base.
 */

class Pool {
  constructor(config) {
    this.config = config;
  }

  async connect() {
    const err = new Error('connect ECONNREFUSED 127.0.0.1:5432');
    err.code = 'ECONNREFUSED';
    err.errno = -111;
    err.syscall = 'connect';
    err.address = '127.0.0.1';
    err.port = 5432;
    throw err;
  }

  async end() {
    // No-op
  }

  on(event, callback) {
    // No-op: the real pool emits 'error' on idle client errors;
    // we have no idle clients so there is nothing to emit.
  }

  query() {
    return Promise.reject(new Error('Database not available in deployment environment'));
  }
}

module.exports = { Pool };

