  1→/**
  2→ * Dispute Review — API Routes
  3→ */
  4→
  5→import { Router, Request, Response } from 'express';
  6→import { z } from 'zod';
  7→import { AppError } from '../../middleware/errorHandler';
  8→import { disputeStore } from './store';
  9→import { reviewDispute } from './agents/orchestrator';
 10→import { runLearningFeedbackAgent } from './agents/learning-feedback-agent';
 11→import { runPrioritizationAgent } from './agents/prioritization-agent';
 12→import { sampleDatasetSchema } from './agents/dataset';
 13→import { datasetToCreateDTO } from './import-dataset';
 14→import { EVIDENCE_URL_PREFIX } from './uploads';
 15→import { precedentStore } from './precedents';
 16→import type { CreateDisputeDTO } from './types';
 17→
 18→export const disputeRouter: Router = Router();
 19→
 20→// Accept the JSON block from the sample markdown directly. This endpoint returns
 21→// the original dispute ID, both submissions and the ruling; it does not persist a case.
 22→disputeRouter.post('/dataset-review', async (req: Request, res: Response) => {
 23→  const dataset = sampleDatasetSchema.parse(req.body);
 24→  const review = await reviewDispute(dataset);
 25→  res.json({ data: review });
 26→});
 27→
 28→/**
 29→ * POST /api/disputes/import-dataset — Turn a sample dataset (DISP-002 JSON block)
 30→ * into a dashboard case. The original dataset is kept and used for the review.
 31→ * A dataset already imported returns its existing case (200, existing: true).
 32→ */
 33→disputeRouter.post('/import-dataset', async (req: Request, res: Response) => {
 34→  const dataset = sampleDatasetSchema.parse(req.body);
 35→  const caseNumber = dataset.dispute_ticket.dispute_id;
 36→  const existing = disputeStore.getAll().find((c) => c.caseNumber === caseNumber);
 37→  if (existing) {
 38→    res.json({ data: existing, existing: true });
 39→    return;
 40→  }
 41→  const created = disputeStore.create(datasetToCreateDTO(dataset), {
 42→    caseNumber,
 43→    dataset,
 44→    createdAt: dataset.dispute_ticket.filed_at,
 45→  });
 46→  const prioritized = disputeStore.setPriorityAssessment(created.id, runPrioritizationAgent(dataset));
 47→  res.status(201).json({ data: prioritized, existing: false });
 48→});
 49→
 50→// ============================================
 51→// Zod validation schema for case creation
 52→// ============================================
 53→const partySchema = z.object({
 54→  name: z.string(),
 55→  id: z.string(),
 56→  rating: z.number(),
 57→  statement: z.string(),
 58→});
 59→
 60→const tripSchema = z.object({
 61→  pickupLocation: z.string(),
 62→  dropoffLocation: z.string(),
 63→  pickupTime: z.string(),
 64→  dropoffTime: z.string(),
 65→  fare: z.number(),
 66→  distance: z.number(),
 67→  vehicleModel: z.string(),
 68→  plateNumber: z.string(),
 69→  currency: z.enum(['CNY', 'SGD']).optional(),
 70→});
 71→
 72→const evidenceInputSchema = z.object({
 73→  party: z.enum(['driver', 'rider', 'platform']),
 74→  kind: z.enum(['text', 'chat', 'gps', 'payment', 'photo']),
 75→  title: z.string(),
 76→  content: z.string(),
 77→  // Set when a file was uploaded through POST /api/uploads
 78→  fileName: z.string().optional(),
 79→  fileUrl: z
 80→    .string()
 81→    .refine((u) => u.startsWith(EVIDENCE_URL_PREFIX) && !u.includes('..'), 'Invalid attachment URL')
 82→    .optional(),
 83→  mimeType: z.string().optional(),
 84→});
 85→
 86→const createDisputeSchema = z.object({
 87→  title: z.string(),
 88→  priority: z.enum(['low', 'medium', 'high', 'urgent']),
 89→  type: z.enum([
 90→    'route_deviation',
 91→    'fare_dispute',
 92→    'no_show_charge',
 93→    'property_damage',
 94→    'safety_accident',
 95→  ]),
 96→  driver: partySchema,
 97→  passenger: partySchema,
 98→  trip: tripSchema,
 99→  evidence: z.array(evidenceInputSchema),
100→});
101→
102→// ============================================
103→// Routes
104→// ============================================
105→
106→/** Human decisions the AI Judge can use as same-type precedents. */
107→disputeRouter.get('/precedents', async (_req: Request, res: Response) => {
108→  res.json({ data: precedentStore.list() });
109→});
110→
111→/** Stop using a human decision as a precedent. */
112→disputeRouter.delete('/precedents/:caseNumber', async (req: Request, res: Response) => {
113→  const caseNumber = String(req.params.caseNumber);
114→  if (!precedentStore.remove(caseNumber)) throw new AppError(404, 'Precedent not found');
115→  disputeStore.unmarkPrecedent(caseNumber);
116→  res.status(204).end();
117→});
118→
119→/**
120→ * GET /api/disputes/stats — Dashboard statistics
121→ */
122→disputeRouter.get('/stats', async (_req: Request, res: Response) => {
123→  res.json({ data: disputeStore.getStats() });
124→});
125→
126→/**
127→ * GET /api/disputes — List all disputes
128→ */
129→disputeRouter.get('/', async (_req: Request, res: Response) => {
130→  res.json({ data: disputeStore.getAll() });
131→});
132→
133→/**
134→ * GET /api/disputes/:id — Get a single dispute
135→ */
136→disputeRouter.get('/:id', async (req: Request, res: Response) => {
137→  const id = String(req.params.id);
138→  const dispute = disputeStore.getById(id);
139→  if (!dispute) {
140→    throw new AppError(404, 'Case not found');
141→  }
142→  res.json({ data: dispute });
143→});
144→
145→/**
146→ * POST /api/disputes — Create a new dispute
147→ */
148→disputeRouter.post('/', async (req: Request, res: Response) => {
149→  const parsed = createDisputeSchema.parse(req.body);
150→  const newCase = disputeStore.create(parsed as CreateDisputeDTO);
151→  const prioritized = disputeStore.setPriorityAssessment(newCase.id, runPrioritizationAgent(newCase));
152→  res.status(201).json({ data: prioritized });
153→});
154→
155→/**
156→ * POST /api/disputes/:id/evidence — Driver or rider adds evidence to a case
157→ */
158→disputeRouter.post('/:id/evidence', async (req: Request, res: Response) => {
159→  const id = String(req.params.id);
160→  const parsed = evidenceInputSchema.parse(req.body);
161→  const updated = disputeStore.addEvidence(id, parsed);
162→  if (!updated) {
163→    throw new AppError(404, 'Case not found');
164→  }
165→  res.status(201).json({ data: updated });
166→});
167→
168→/**
169→ * POST /api/disputes/:id/review — Trigger AI review
170→ */
171→disputeRouter.post('/:id/review', async (req: Request, res: Response) => {
172→  const id = String(req.params.id);
173→  const dispute = disputeStore.getById(id);
174→  if (!dispute) {
175→    throw new AppError(404, 'Case not found');
176→  }
177→
178→  // Preserve the previous status if execution itself fails (for example, a
179→  // human-decided case must not be reopened by a failed retry).
180→  const previousStatus = dispute.status;
181→  disputeStore.setStatus(id, 'under_review');
182→
183→  try {
184→    // Imported dataset cases are reviewed on the original dataset (precise citations)
185→    const review = await reviewDispute(dispute.dataset ?? dispute);
186→    // The store decides the status: resolved / needs a human / retry after failure
187→    const updated = disputeStore.updateReview(id, review);
188→    res.json({ data: updated });
189→  } catch (error) {
190→    disputeStore.setStatus(id, previousStatus);
191→    const message =
192→      error instanceof Error ? error.message : 'AI review failed. Please try again.';
193→    throw new AppError(500, message);
194→  }
195→});
196→
197→/**
198→ * POST /api/disputes/:id/override — A human reviewer decides the case
199→ */
200→const overrideSchema = z.object({
201→  recommendation: z.enum(['driver', 'passenger', 'shared', 'inconclusive']),
202→  reason: z.string().trim().min(1, 'Please give a reason for the decision').max(2000),
203→  decidedBy: z.string().trim().max(100).optional().transform((value) => value || undefined),
204→  useAsPrecedent: z.boolean().default(true),
205→});
206→
207→disputeRouter.post('/:id/override', async (req: Request, res: Response) => {
208→  const id = String(req.params.id);
209→  let updated = disputeStore.override(id, overrideSchema.parse(req.body));
210→  if (!updated) {
211→    throw new AppError(404, 'Case not found');
212→  }
213→  const feedback = await runLearningFeedbackAgent(updated);
214→  updated = disputeStore.setLearningFeedback(id, feedback) ?? updated;
215→  res.json({ data: updated });
216→});
217→
218→/** Withdraw a human decision and its learning records. */
219→disputeRouter.delete('/:id/override', async (req: Request, res: Response) => {
220→  const updated = disputeStore.clearOverride(String(req.params.id));
221→  if (!updated) {
222→    throw new AppError(404, 'Case not found');
223→  }
224→  res.json({ data: updated });
225→});
226→

