  1→import { Annotation, END, START, StateGraph } from '@langchain/langgraph';
  2→import type {
  3→  AdvocateCase,
  4→  AgentInput,
  5→  EscalationDecision,
  6→  EvidenceValidation,
  7→  FraudAssessment,
  8→  JudgeReview,
  9→  MultiAgentReview,
 10→  PriorityAssessment,
 11→  ReviewWorkflowStatus,
 12→} from './contracts';
 13→import { runDriverAdvocate } from './driver-advocate';
 14→import { runEscalationAgent } from './escalation-agent';
 15→import { runEvidenceValidationAgent } from './evidence-validation-agent';
 16→import { runFraudAgent } from './fraud-agent';
 17→import { runJudge } from './judge';
 18→import { runPrioritizationAgent } from './prioritization-agent';
 19→import { runRiderAdvocate } from './rider-advocate';
 20→import { disputeId, validateInput } from './shared';
 21→import { disputeType } from './checklist';
 22→import { precedentStore } from '../precedents';
 23→
 24→const ReviewState = Annotation.Root({
 25→  input: Annotation<AgentInput>(),
 26→  priorityAssessment: Annotation<PriorityAssessment>(),
 27→  evidenceValidation: Annotation<EvidenceValidation>(),
 28→  fraud: Annotation<FraudAssessment>(),
 29→  rider: Annotation<AdvocateCase>(),
 30→  driver: Annotation<AdvocateCase>(),
 31→  ruling: Annotation<JudgeReview>(),
 32→  escalation: Annotation<EscalationDecision>(),
 33→  workflowStatus: Annotation<ReviewWorkflowStatus>(),
 34→});
 35→
 36→/**
 37→ * LangGraph workflow: priority -> evidence validation -> parallel advocates and
 38→ * fraud/bad-faith detection -> Judge -> confidence routing -> automatic
 39→ * resolution or human intervention.
 40→ */
 41→export const disputeReviewGraph = new StateGraph(ReviewState)
 42→  .addNode('prioritization', (state) => ({
 43→    priorityAssessment: runPrioritizationAgent(state.input),
 44→  }))
 45→  .addNode('evidence_validation', (state) => ({
 46→    evidenceValidation: runEvidenceValidationAgent(state.input),
 47→  }))
 48→  .addNode('fraud_detection', (state) => ({
 49→    fraud: runFraudAgent(state.input),
 50→  }))
 51→  .addNode('rider_advocate', async (state) => ({
 52→    rider: await runRiderAdvocate(state.input),
 53→  }))
 54→  .addNode('driver_advocate', async (state) => ({
 55→    driver: await runDriverAdvocate(state.input),
 56→  }))
 57→  .addNode('judge', async (state) => ({
 58→    ruling: await runJudge(
 59→      state.input,
 60→      state.rider,
 61→      state.driver,
 62→      precedentStore.select(disputeType(state.input), disputeId(state.input)),
 63→      state.fraud
 64→    ),
 65→  }))
 66→  .addNode('confidence_escalation', (state) => ({
 67→    escalation: runEscalationAgent(state.ruling, state.input),
 68→  }))
 69→  .addNode('automatic_resolution', () => ({
 70→    workflowStatus: 'auto_resolved' as const,
 71→  }))
 72→  .addNode('human_intervention', () => ({
 73→    workflowStatus: 'human_intervention_required' as const,
 74→  }))
 75→  .addEdge(START, 'prioritization')
 76→  .addEdge('prioritization', 'evidence_validation')
 77→  .addEdge('evidence_validation', 'rider_advocate')
 78→  .addEdge('evidence_validation', 'driver_advocate')
 79→  .addEdge('evidence_validation', 'fraud_detection')
 80→  .addEdge(['rider_advocate', 'driver_advocate', 'fraud_detection'], 'judge')
 81→  .addEdge('judge', 'confidence_escalation')
 82→  .addConditionalEdges(
 83→    'confidence_escalation',
 84→    (state) => state.escalation.needsHuman ? 'human' : 'automatic',
 85→    { human: 'human_intervention', automatic: 'automatic_resolution' }
 86→  )
 87→  .addEdge('automatic_resolution', END)
 88→  .addEdge('human_intervention', END)
 89→  .compile();
 90→
 91→export async function reviewDispute(input: AgentInput): Promise<MultiAgentReview> {
 92→  const state = await disputeReviewGraph.invoke({ input: validateInput(input) });
 93→  if (!state.ruling || !state.rider || !state.driver || !state.priorityAssessment ||
 94→      !state.evidenceValidation || !state.fraud || !state.escalation || !state.workflowStatus) {
 95→    throw new Error('LangGraph review finished without a complete workflow state.');
 96→  }
 97→  return {
 98→    ...state.ruling,
 99→    advocateSubmissions: { rider: state.rider, driver: state.driver },
100→    priorityAssessment: state.priorityAssessment,
101→    evidenceValidation: state.evidenceValidation,
102→    fraudAssessment: state.fraud,
103→    escalation: state.escalation,
104→    workflowStatus: state.workflowStatus,
105→  };
106→}
