 1→import { chatCompletion } from '../../../lib/llm-chat';
 2→import { advocateOutputSchema, type AgentInput, type AdvocateCase, type AdvocateRole } from './contracts';
 3→import {
 4→  isFareDisputeDataset,
 5→  isLegacyRouteDeviationDataset,
 6→  isStructuredRouteDeviationDataset,
 7→} from './dataset';
 8→import {
 9→  checkAdvocateSources, disputeId, evidenceInstructions,
10→  formatCaseContext, groundedPolicyArguments, parseJsonObject, validateInput,
11→} from './shared';
12→import { createLogger } from '../../../config/logger';
13→
14→const logger = createLogger('Agents');
15→
16→/** Shared transport and validation; advocates use distinct roles and prompts. */
17→export async function runAdvocate(input: AgentInput, agent: AdvocateRole): Promise<AdvocateCase> {
18→  const record = validateInput(input);
19→  const party = agent === 'rider_advocate' ? 'rider' : 'driver';
20→  // Example citations that exist in this kind of record
21→  const policyExample = isLegacyRouteDeviationDataset(record)
22→    ? '["/fare_policy/deviation_tolerance_pct","/computed_route_analysis/deviation_pct"]'
23→    : isStructuredRouteDeviationDataset(record)
24→      ? '["/applicable_policy/route_deviation/distance_tolerance_km","/computed_route_analysis/extra_distance_km"]'
25→      : isFareDisputeDataset(record)
26→        ? '["/applicable_policy/fare_and_surge/unnotified_surge_refund","/trip_data/fare_difference"]'
27→        : '["/applicable_policy/no_show/free_wait_time_min","/trip_data/cancellation_time"]';
28→  const prompt = `You are the ${party} advocate. Gather relevant material from the provided
29→record and present the strongest honest case for the ${party}, acknowledging adverse evidence.
30→${evidenceInstructions}
31→Return only this JSON shape:
32→{
33→  "positionSummary": "party position",
34→  "claims": ["allegations or claims, with attribution"],
35→  "supportingEvidence": [{"evidence":"fact or allegation","relevance":"why it matters","sourceRefs":["/path"]}],
36→  "adverseEvidence": [{"evidence":"adverse fact","relevance":"why it weakens the case","sourceRefs":["/path"]}],
37→  "policyArguments": [{"argument":"application of supplied policy","sourceRefs":${policyExample}}],
38→  "missingEvidence": ["missing facts or conflicting timestamps"],
39→  "requestedOutcome": "specific requested remedy, including SGD amount when supported",
40→  "confidenceScore": "integer from 0 to 100"
41→}
42→Use empty arrays when there is no evidence or supplied policy. Never fabricate a citation.`;
43→  try {
44→    const text = await chatCompletion([
45→      { role: 'system', content: prompt },
46→      { role: 'user', content: formatCaseContext(record) },
47→    ], { temperature: 0.2, max_tokens: 2600 });
48→    const parsed = advocateOutputSchema.parse(parseJsonObject(text));
49→    const { kept, dropped } = groundedPolicyArguments(parsed.policyArguments, record);
50→    if (dropped) logger.warn({ agent, dropped }, 'Dropped policy arguments that cite no supplied policy');
51→    const output: AdvocateCase = {
52→      ...parsed, policyArguments: kept,
53→      agent, disputeId: disputeId(record), mode: 'llm',
54→    };
55→    checkAdvocateSources(output, record);
56→    return output;
57→  } catch (err) {
58→    logger.warn({ agent, err: err instanceof Error ? err.message : String(err) }, 'Advocate output unavailable or invalid');
59→    return {
60→      agent, disputeId: disputeId(record), mode: 'fallback',
61→      positionSummary: `The ${party} submission could not be generated or validated.`,
62→      claims: ['No model-assessed claims are available.'],
63→      supportingEvidence: [], adverseEvidence: [], policyArguments: [],
64→      missingEvidence: ['A valid model-generated assessment of the supplied evidence is unavailable.'],
65→      requestedOutcome: 'No merits recommendation; retry analysis.',
66→      confidenceScore: 0,
67→    };
68→  }
69→}
