  1→import { chatCompletion } from '../../../lib/llm-chat';
  2→import {
  3→  judgeOutputSchema, type AgentInput, type AdvocateCase, type FraudAssessment,
  4→  type JudgeOutput, type JudgeReview,
  5→} from './contracts';
  6→import {
  7→  assertSourceRefs, checkAdvocateSources, disputeId, evidenceInstructions,
  8→  formatCaseContext, parseJsonObject, validateInput,
  9→} from './shared';
 10→import { createLogger } from '../../../config/logger';
 11→import type { ChecklistAnswer, Resolution } from '../types';
 12→import {
 13→  isDataset,
 14→  isFareDisputeDataset,
 15→  isLegacyRouteDeviationDataset,
 16→  isNoShowDataset,
 17→  isStructuredRouteDeviationDataset,
 18→} from './dataset';
 19→import type { Precedent } from '../precedents';
 20→import { judgeChecklist, type ChecklistItem } from './checklist';
 21→
 22→const logger = createLogger('Agents');
 23→
 24→function unavailable(input: AgentInput): JudgeReview {
 25→  return {
 26→    disputeId: disputeId(input), mode: 'fallback',
 27→    summary: 'Inconclusive: the three-agent review could not be completed.',
 28→    keyIssues: ['A validated assessment from both advocates and the Judge is required.'],
 29→    driverPerspective: 'No final assessment is available.',
 30→    passengerPerspective: 'No final assessment is available.',
 31→    evidenceAnalysis: 'The input is retained, but no reliable automated merits decision was completed.',
 32→    policyReferences: [], recommendation: 'inconclusive',
 33→    recommendationReasoning: 'No decision is inferred from ratings, statement length, or missing model output.',
 34→    suggestedActions: ['Retry the review; make no refund or compensation adjustment from this result.'],
 35→    resolution: {
 36→      action: 'no_action', amount: 0, currency: currency(input), recipient: 'none',
 37→      basis: 'No automated decision; retry the review or decide manually.',
 38→    },
 39→    confidenceScore: 0,
 40→    confidenceReasoning: 'Model output was unavailable or failed validation.',
 41→    sourceRefs: [], missingEvidence: ['A complete validated model assessment.'],
 42→    reviewedAt: new Date().toISOString(),
 43→  };
 44→}
 45→
 46→function currency(input: AgentInput): Resolution['currency'] {
 47→  return isDataset(input) ? 'SGD' : input.trip.currency ?? 'CNY';
 48→}
 49→
 50→/** The charge under dispute: no refund or compensation may exceed it. */
 51→function disputedAmount(input: AgentInput): number {
 52→  if (isNoShowDataset(input)) return input.trip_data.cancellation_fee;
 53→  if (isLegacyRouteDeviationDataset(input)) return input.trip_data.final_fare;
 54→  if (isStructuredRouteDeviationDataset(input)) return input.trip_data.excess_fare;
 55→  if (isFareDisputeDataset(input)) return input.trip_data.fare_difference;
 56→  if ('dispute_ticket' in input) return 0;
 57→  return input.trip.fare;
 58→}
 59→
 60→/**
 61→ * Compensation may legitimately exceed the disputed charge (e.g. a rider is owed
 62→ * more than the fare for a loss). Other actions (refunds) are capped at the charge.
 63→ */
 64→const COMPENSATION_CAP_MULTIPLIER = 2;
 65→
 66→/** The ruling must name a concrete, internally consistent outcome that fits the disputed charge. */
 67→function checkedResolution(output: JudgeOutput, input: AgentInput): Resolution {
 68→  const { action, amount, recipient, basis } = output.resolution;
 69→  if (action === 'no_action') {
 70→    if (amount !== 0 || recipient !== 'none') throw new Error('no_action must have amount 0 and recipient none');
 71→  } else {
 72→    if (amount <= 0 || recipient === 'none') throw new Error(`${action} needs a positive amount and a recipient`);
 73→    const cap = action === 'compensation'
 74→      ? disputedAmount(input) * COMPENSATION_CAP_MULTIPLIER
 75→      : disputedAmount(input);
 76→    if (amount > cap + 0.005) {
 77→      throw new Error(`${action} of ${amount} exceeds the cap of ${cap} (disputed charge ${disputedAmount(input)})`);
 78→    }
 79→  }
 80→  if (output.recommendation === 'inconclusive' && action !== 'no_action') {
 81→    throw new Error('An inconclusive ruling cannot move money');
 82→  }
 83→  return { action, amount, currency: currency(input), recipient, basis };
 84→}
 85→
 86→/** Every required check answered once, in order, with citations that exist in the record. */
 87→function checklistAnswers(
 88→  required: ChecklistItem[], output: JudgeOutput, input: AgentInput
 89→): ChecklistAnswer[] {
 90→  const answers = required.map(({ id, item }) => {
 91→    const answer = output.checklist.find((a) => a.id.trim().toUpperCase() === id);
 92→    if (!answer) throw new Error(`Judge skipped checklist item ${id}`);
 93→    return { id, item, finding: answer.finding, conflict: answer.conflict, sourceRefs: answer.sourceRefs };
 94→  });
 95→  assertSourceRefs(answers.flatMap((a) => a.sourceRefs), input);
 96→  return answers;
 97→}
 98→
 99→/**
100→ * Every flagged conflict must surface to the reviewer. When the Judge flags one
101→ * but lists nothing (typically a claim it considers settled by the records), its
102→ * finding is listed instead of discarding an otherwise valid ruling.
103→ */
104→function withConflictsListed(missing: string[], answers: ChecklistAnswer[]): string[] {
105→  if (missing.length > 0) return missing;
106→  return answers.filter((a) => a.conflict).map((a) => `Conflict at ${a.id} (${a.item}): ${a.finding}`);
107→}
108→
109→export async function runJudge(
110→  input: AgentInput, riderCase: AdvocateCase, driverCase: AdvocateCase,
111→  precedents: Precedent[] = [], fraud?: FraudAssessment
112→): Promise<JudgeReview> {
113→  const record = validateInput(input);
114→  // Do not silently judge from one successful advocate and one template fallback.
115→  if (riderCase.mode !== 'llm' || driverCase.mode !== 'llm') return unavailable(record);
116→  let output: JudgeOutput | undefined;
117→  try {
118→    checkAdvocateSources(riderCase, record);
119→    checkAdvocateSources(driverCase, record);
120→    if (riderCase.agent !== 'rider_advocate' || driverCase.agent !== 'driver_advocate') {
121→      throw new Error('Unexpected advocate roles');
122→    }
123→    const required = judgeChecklist(record);
124→    const response = await chatCompletion([
125→      {
126→        role: 'system',
127→        content: `You are the impartial Judge. Weigh both submissions against the original record.
128→${evidenceInstructions}
129→Advocate arguments are not additional evidence. Do not simply average their confidence.
130→For no-show charges, explicitly explain whether the fee is upheld, reversed or inconclusive,
131→the SGD amount, and who receives it. If deciding despite conflicting timer records, explain
132→your policy interpretation and lower confidence as appropriate.
133→For route deviations, decide whether the deviation was justified (rider request or agreement, a
134→policy exemption supported by the record), whether notice was given, and the excess-distance refund.
135→For fare disputes, compare the binding upfront quote with the actual fare and refund an unnotified
136→surge differential under Policy v2.1 §3. Safety-related disputes receive no AI merits ruling.
137→resolution is the concrete outcome, in ${currency(record)}:
138→- full_refund: return the whole disputed charge to the rider
139→- partial_refund: return part of it to the rider (e.g. the overcharge above the upfront estimate)
140→- compensation: pay a party for a loss caused by the other party or the platform (may exceed the disputed charge, up to ${disputedAmount(record) * COMPENSATION_CAP_MULTIPLIER} ${currency(record)})
141→- no_action: the charge stands (e.g. a no-show fee is upheld and stays with the driver); amount 0,
142→  recipient "none". Use no_action when the ruling is inconclusive.
143→Refunds (full_refund, partial_refund) can never exceed the disputed charge (${disputedAmount(record)} ${currency(record)}). Show the calculation in basis.
144→partyNotices are short messages (3-5 sentences) sent to each party: plain, respectful language
145→addressed to that person ("you"), stating the outcome, any amount and when it applies, the main
146→reason in everyday terms, and that they can reply to appeal. No JSON paths, internal agent names or
147→confidence scores, and nothing about the other party beyond what the decision needs.
148→Before ruling, answer every item in requiredChecklist, by its id. For each, state what the record
149→shows, set conflict to true when sources disagree, and cite sourceRefs (an empty array when nothing
150→in the record addresses it). For every conflict, add an entry to missingEvidence saying whether it is
151→resolved by the records (and how) or still open, and reflect open conflicts in confidenceReasoning.
152→humanPrecedents (may be empty) are earlier disputes of this type decided by human reviewers, with
153→their reasons. Use them only to calibrate standards: how the policy is applied and how records are
154→weighed against statements. They are not evidence about this case, are never cited in sourceRefs and
155→never override this record. Where this case differs materially, rule on its own facts.
156→fraudRiskSignals (may be absent) are risk context the system computed from each party's profile and
157→dispute history. They are context, never evidence: they prove nothing about this trip, they are never
158→cited in sourceRefs, and they must not change the ruling on their own. A flagged or high-frequency
159→account can still be the wronged party. Use them only to explain, in confidenceReasoning, that you
160→weighed them and why they did not decide the outcome. Never raise or lower confidence to match them.
161→Return only this JSON object:
162→{
163→ "summary":"ruling summary", "keyIssues":["issue"],
164→ "driverPerspective":"assessment", "passengerPerspective":"assessment",
165→ "evidenceAnalysis":"evidence comparison", "policyReferences":["supplied policy and exact value"],
166→ "recommendation":"driver|passenger|shared|inconclusive",
167→ "recommendationReasoning":"ruling with source-grounded explanation",
168→ "suggestedActions":["specific action including amount and recipient when justified"],
169→ "confidenceScore":"integer from 0 to 100", "confidenceReasoning":"uncertainties",
170→ "sourceRefs":["/existing/source/path"], "missingEvidence":["missing facts or unresolved conflicts"],
171→ "checklist":[{"id":"C1","finding":"what the record shows","conflict":false,"sourceRefs":["/existing/source/path"]}],
172→ "resolution":{"action":"full_refund|partial_refund|compensation|no_action","amount":0,"recipient":"rider|driver|none","basis":"calculation from policy and record"},
173→ "partyNotices":{"rider":"message to the rider","driver":"message to the driver"}
174→}
175→Select one value for each enum field. Do not output the pipe-separated examples literally.`,
176→      },
177→      {
178→        role: 'user',
179→        content: JSON.stringify({
180→          ...JSON.parse(formatCaseContext(record)),
181→          riderAdvocateSubmission: riderCase,
182→          driverAdvocateSubmission: driverCase,
183→          requiredChecklist: required,
184→          // Deliberately without sourceRefs: these are context, not citable record paths.
185→          ...(fraud && fraud.signals.length > 0 ? {
186→            fraudRiskSignals: {
187→              riskLevel: fraud.riskLevel,
188→              note: fraud.note,
189→              signals: fraud.signals.map((s) => ({
190→                party: s.party, code: s.code, severity: s.severity, detail: s.detail,
191→              })),
192→            },
193→          } : {}),
194→          humanPrecedents: precedents.map((p) => ({
195→            caseNumber: p.caseNumber, title: p.title, facts: p.facts,
196→            aiRecommendation: p.aiRecommendation, humanDecision: p.humanRecommendation, humanReason: p.reason,
197→          })),
198→        }),
199→      },
200→    ], { temperature: 0.1, max_tokens: 3000 });
201→    output = judgeOutputSchema.parse(parseJsonObject(response));
202→    assertSourceRefs(output.sourceRefs, record);
203→    const checklist = checklistAnswers(required, output, record);
204→    return {
205→      ...output,
206→      resolution: checkedResolution(output, record),
207→      checklist,
208→      missingEvidence: withConflictsListed(output.missingEvidence, checklist),
209→      precedentsUsed: precedents.map((p) => p.caseNumber),
210→      disputeId: disputeId(record), mode: 'llm',
211→      reviewedAt: new Date().toISOString(),
212→    };
213→  } catch (err) {
214→    const msg = err instanceof Error ? err.message : String(err);
215→    logger.warn({
216→      agent: 'judge',
217→      err: msg,
218→      disputeId: disputeId(record),
219→      disputedAmount: disputedAmount(record),
220→      ...(output?.resolution && {
221→        action: output.resolution.action,
222→        attemptedAmount: output.resolution.amount,
223→        recipient: output.resolution.recipient,
224→      }),
225→    }, 'Judge output unavailable or invalid');
226→    return unavailable(record);
227→  }
