  1→/**
  2→ * Chat client for the dispute-review agents (OpenAI-compatible APIs).
  3→ *
  4→ * Provider order (LLM_PROVIDER=gemini or tokenhub forces one):
  5→ *   1. Google Gemini (free tier) when GEMINI_API_KEY is set — GEMINI_MODEL first,
  6→ *      then each of GEMINI_FALLBACK_MODELS if a call fails (high demand, quota,
  7→ *      retired model, stalled or too slow).
  8→ *   2. Tencent TokenHub (hy3) when TOKENHUB_API_KEY is set, or inside the
  9→ *      Genie sandbox proxy.
 10→ * With neither, calls throw and the agents return their explicit fallback.
 11→ */
 12→
 13→import OpenAI from 'openai';
 14→import { env } from '../config/env';
 15→import { createLogger } from '../config/logger';
 16→
 17→const logger = createLogger('LLM');
 18→
 19→const GEMINI_BASE_URL = 'https://generativelanguage.googleapis.com/v1beta/openai/';
 20→// Gemini models think before answering and the thinking counts toward the
 21→// output limit, so a small max_tokens can cut the JSON answer short.
 22→const GEMINI_MIN_OUTPUT_TOKENS = 8192;
 23→
 24→export interface ChatMessage {
 25→  role: 'system' | 'user' | 'assistant';
 26→  content: string;
 27→}
 28→
 29→export interface ChatOptions {
 30→  temperature?: number;
 31→  max_tokens?: number;
 32→}
 33→
 34→interface Provider {
 35→  name: 'gemini' | 'tokenhub';
 36→  client: OpenAI;
 37→  models: string[];
 38→  minOutputTokens: number;
 39→  reasoningEffort?: 'low' | 'medium' | 'high';
 40→}
 41→
 42→function resolveProvider(): Provider | null {
 43→  if (env.GEMINI_API_KEY && env.LLM_PROVIDER !== 'tokenhub') {
 44→    return {
 45→      name: 'gemini',
 46→      client: new OpenAI({
 47→        apiKey: env.GEMINI_API_KEY,
 48→        baseURL: GEMINI_BASE_URL,
 49→        timeout: env.LLM_TIMEOUT_MS,
 50→        // One retry for "high demand" 503s and 429s, then the next model is tried
 51→        maxRetries: 1,
 52→      }),
 53→      models: [env.GEMINI_MODEL, ...env.GEMINI_FALLBACK_MODELS.filter((m) => m !== env.GEMINI_MODEL)],
 54→      minOutputTokens: GEMINI_MIN_OUTPUT_TOKENS,
 55→      reasoningEffort: env.GEMINI_REASONING_EFFORT,
 56→    };
 57→  }
 58→
 59→  if (env.LLM_PROVIDER === 'gemini') return null;
 60→  const isSandbox = process.env.X_IDE_AUTH_PROXY !== undefined;
 61→  const apiKey = env.TOKENHUB_API_KEY || (isSandbox ? 'mock_api_key' : '');
 62→  if (!apiKey) return null;
 63→  const useSandbox = isSandbox && apiKey === 'mock_api_key';
 64→  return {
 65→    name: 'tokenhub',
 66→    client: new OpenAI({
 67→      apiKey,
 68→      baseURL: useSandbox ? 'http://tokenhub.openai.auth-proxy.local/v1' : env.TOKENHUB_BASE_URL,
 69→      timeout: env.LLM_TIMEOUT_MS,
 70→      maxRetries: 1,
 71→    }),
 72→    models: [env.TOKENHUB_MODEL],
 73→    minOutputTokens: 0,
 74→  };
 75→}
 76→
 77→let provider: Provider | null | undefined;
 78→
 79→// A model that answered 429 (free-tier daily or per-minute quota) is skipped for a while
 80→// so every later call does not spend a request finding out again.
 81→const QUOTA_COOLDOWN_MS = 10 * 60_000;
 82→const coolingUntil = new Map<string, number>();
 83→
 84→function getProvider(): Provider {
 85→  if (provider === undefined) provider = resolveProvider();
 86→  if (!provider) {
 87→    throw new Error('No LLM API key configured (set GEMINI_API_KEY or TOKENHUB_API_KEY)');
 88→  }
 89→  return provider;
 90→}
 91→
 92→/** Which provider and models the agents will use; for health checks and logs. */
 93→export function llmInfo(): { provider: string; models: string[] } | null {
 94→  try {
 95→    const p = getProvider();
 96→    return { provider: p.name, models: p.models };
 97→  } catch {
 98→    return null;
 99→  }
100→}
101→
102→/**
103→ * One streamed completion. Free-tier models can be slow but steady, so instead of
104→ * a single deadline the call is abandoned when no output arrives for
105→ * LLM_IDLE_TIMEOUT_MS, or when it runs longer than LLM_TIMEOUT_MS in total.
106→ */
107→async function streamCompletion(
108→  p: Provider,
109→  model: string,
110→  messages: ChatMessage[],
111→  options: ChatOptions
112→): Promise<string> {
113→  const controller = new AbortController();
114→  const total = setTimeout(() => controller.abort(new Error('total time limit reached')), env.LLM_TIMEOUT_MS);
115→  let idle: NodeJS.Timeout | undefined;
116→  const resetIdle = () => {
117→    clearTimeout(idle);
118→    idle = setTimeout(() => controller.abort(new Error('no output, model stalled')), env.LLM_IDLE_TIMEOUT_MS);
119→  };
120→
121→  try {
122→    resetIdle();
123→    const stream = await p.client.chat.completions.create(
124→      {
125→        model,
126→        messages: messages as OpenAI.Chat.ChatCompletionMessageParam[],
127→        temperature: options.temperature ?? 0.2,
128→        max_tokens: Math.max(options.max_tokens ?? 4096, p.minOutputTokens),
129→        ...(p.reasoningEffort ? { reasoning_effort: p.reasoningEffort } : {}),
130→        stream: true,
131→      },
132→      { signal: controller.signal }
133→    );
134→
135→    let content = '';
136→    let finishReason: string | null = null;
137→    for await (const chunk of stream) {
138→      resetIdle();
139→      const choice = chunk.choices[0];
140→      content += choice?.delta?.content ?? '';
141→      finishReason = choice?.finish_reason ?? finishReason;
142→    }
143→    if (finishReason === 'length') throw new Error(`${model} hit the output token limit before finishing`);
144→    if (!content) throw new Error(`${model} returned an empty response`);
145→    return content;
146→  } catch (err) {
147→    // Report why we aborted rather than the SDK's generic "Request was aborted"
148→    if (controller.signal.aborted) throw new Error(`${model}: ${String(controller.signal.reason?.message)}`);
149→    throw err;
150→  } finally {
151→    clearTimeout(total);
152→    clearTimeout(idle);
153→  }
154→}
155→
156→/**
157→ * Chat completion. Returns the assistant's text content.
158→ * Tries each configured model in turn; throws the last error if all fail.
159→ */
160→export async function chatCompletion(
161→  messages: ChatMessage[],
162→  options: ChatOptions = {}
163→): Promise<string> {
164→  const p = getProvider();
165→  let lastError: unknown;
166→
167→  const now = Date.now();
168→  const available = p.models.filter((m) => (coolingUntil.get(m) ?? 0) <= now);
169→  // If every model is cooling down, try them all anyway rather than fail outright
170→  for (const model of available.length ? available : p.models) {
171→    try {
172→      return await streamCompletion(p, model, messages, options);
173→    } catch (err) {
174→      lastError = err;
175→      if (err instanceof OpenAI.APIError && err.status === 429) {
176→        coolingUntil.set(model, Date.now() + QUOTA_COOLDOWN_MS);
177→      }
178→      logger.warn(
179→        { provider: p.name, model, err: err instanceof Error ? err.message : String(err) },
180→        'LLM call failed; trying the next model if any'
181→      );
182→    }
183→  }
184→  throw lastError;
185→}
