import OpenAI from 'openai';
import { env } from '../config/env';
import { createLogger } from '../config/logger';

const logger = createLogger('LLM');

// ---------------------------------------------------------------------------
// WorkBuddy Cloud SDK — loaded dynamically so the package is optional.
// If it is not installed, the WorkBuddy provider is simply unavailable.
// ---------------------------------------------------------------------------
// eslint-disable-next-line @typescript-eslint/no-explicit-any
let createWorkBuddyCloud: ((opts: Record<string, unknown>) => any) | null = null;
try {
  // eslint-disable-next-line @typescript-eslint/no-var-requires, @typescript-eslint/no-require-imports
  const wb = require('@tencent-ai/workbuddy-cloud-sdk');
  createWorkBuddyCloud = wb.createWorkBuddyCloud ?? wb.default?.createWorkBuddyCloud ?? null;
} catch {
  createWorkBuddyCloud = null;
}

const GEMINI_BASE_URL = 'https://generativelanguage.googleapis.com/v1beta/openai/';
// Gemini models think before answering and the thinking counts toward the
// output limit, so a small max_tokens can cut the JSON answer short.
const GEMINI_MIN_OUTPUT_TOKENS = 8192;

export interface ChatMessage {
  role: 'system' | 'user' | 'assistant';
  content: string;
}

export interface ChatOptions {
  temperature?: number;
  max_tokens?: number;
}

interface Provider {
  name: 'gemini' | 'tokenhub' | 'workbuddy';
  /** 'openai' for the OpenAI SDK, 'workbuddy' for the WorkBuddy Cloud SDK */
  kind: 'openai' | 'workbuddy';
  /** OpenAI instance (openai) or WorkBuddy cloud instance (workbuddy) */
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  client: any;
  models: string[];
  minOutputTokens: number;
  reasoningEffort?: 'low' | 'medium' | 'high';
}

function resolveWorkBuddyProvider(): Provider | null {
  if (!env.WORKBUDDY_CLOUD_ENDPOINT || !env.WORKBUDDY_CLOUD_PUBLISHABLE_KEY) {
    return null;
  }
  if (!env.WORKBUDDY_CLOUD_MODEL) {
    logger.warn(
      'WorkBuddy Cloud endpoint and key are set but WORKBUDDY_CLOUD_MODEL is empty; '
      + 'set it to a model id from cloud.llm.models.list()',
    );
    return null;
  }
  if (!createWorkBuddyCloud) {
    logger.warn(
      '@tencent-ai/workbuddy-cloud-sdk is not installed; WorkBuddy provider unavailable. '
      + 'Run: npm install @tencent-ai/workbuddy-cloud-sdk',
    );
    return null;
  }
  const cloud = createWorkBuddyCloud({
    endpoint: env.WORKBUDDY_CLOUD_ENDPOINT,
    publishableKey: env.WORKBUDDY_CLOUD_PUBLISHABLE_KEY,
  });
  return {
    name: 'workbuddy',
    kind: 'workbuddy',
    client: cloud,
    models: [env.WORKBUDDY_CLOUD_MODEL],
    minOutputTokens: 0,
  };
}

function resolveProvider(): Provider | null {
  // 1. WorkBuddy Cloud (keyless, uses WorkBuddy credits)
  if (env.LLM_PROVIDER === 'workbuddy' || (env.LLM_PROVIDER === 'auto' && env.WORKBUDDY_CLOUD_ENDPOINT)) {
    const wb = resolveWorkBuddyProvider();
    if (wb) return wb;
    // If explicitly requested but not configured, fall through to other providers
    if (env.LLM_PROVIDER === 'workbuddy') return null;
