        apiKey: env.GEMINI_API_KEY,
        baseURL: GEMINI_BASE_URL,
        timeout: env.LLM_TIMEOUT_MS,
        // One retry for "high demand" 503s and 429s, then the next model is tried
        maxRetries: 1,
