 19→const logger = createLogger('LLM');
 20→
 21→// ---------------------------------------------------------------------------
 22→// WorkBuddy Cloud SDK — loaded dynamically so the package is optional.
 23→// If it is not installed, the WorkBuddy provider is simply unavailable.
 24→// ---------------------------------------------------------------------------
 25→// eslint-disable-next-line @typescript-eslint/no-explicit-any
 26→let createWorkBuddyCloud: ((opts: Record<string, unknown>) => any) | null = null;
 27→try {
 28→  // eslint-disable-next-line @typescript-eslint/no-var-requires, @typescript-eslint/no-require-imports
 29→  const wb = require('@tencent-ai/workbuddy-cloud-sdk');
 30→  createWorkBuddyCloud = wb.createWorkBuddyCloud ?? wb.default?.createWorkBuddyCloud ?? null;
 31→} catch {
 32→  createWorkBuddyCloud = null;
 33→}
 34→
 35→const GEMINI_BASE_URL = 'https://generativelanguage.googleapis.com/v1beta/openai/';
 36→// Gemini models think before answering and the thinking counts toward the
 37→// output limit, so a small max_tokens can cut the JSON answer short.
 38→const GEMINI_MIN_OUTPUT_TOKENS = 8192;
 39→
 40→export interface ChatMessage {
 41→  role: 'system' | 'user' | 'assistant';
 42→  content: string;
 43→}
 44→
 45→export interface ChatOptions {
 46→  temperature?: number;
 47→  max_tokens?: number;
 48→}
 49→
 50→interface Provider {
 51→  name: 'gemini' | 'tokenhub' | 'workbuddy';
 52→  /** 'openai' for the OpenAI SDK, 'workbuddy' for the WorkBuddy Cloud SDK */
 53→  kind: 'openai' | 'workbuddy';
 54→  /** OpenAI instance (openai) or WorkBuddy cloud instance (workbuddy) */
 55→  // eslint-disable-next-line @typescript-eslint/no-explicit-any
 56→  client: any;
 57→  models: string[];
 58→  minOutputTokens: number;
 59→  reasoningEffort?: 'low' | 'medium' | 'high';
 60→}
 61→
 62→function resolveWorkBuddyProvider(): Provider | null {
 63→  if (!env.WORKBUDDY_CLOUD_ENDPOINT || !env.WORKBUDDY_CLOUD_PUBLISHABLE_KEY) {
 64→    return null;
 65→  }
 66→  if (!env.WORKBUDDY_CLOUD_MODEL) {
 67→    logger.warn(
 68→      'WorkBuddy Cloud endpoint and key are set but WORKBUDDY_CLOUD_MODEL is empty; '
 69→      + 'set it to a model id from cloud.llm.models.list()',
 70→    );
 71→    return null;
 72→  }
 73→  if (!createWorkBuddyCloud) {
 74→    logger.warn(
 75→      '@tencent-ai/workbuddy-cloud-sdk is not installed; WorkBuddy provider unavailable. '
 76→      + 'Run: npm install @tencent-ai/workbuddy-cloud-sdk',
 77→    );
 78→    return null;
 79→  }
 80→  let cloud: unknown;
 81→  try {
 82→    cloud = createWorkBuddyCloud({
 83→      endpoint: env.WORKBUDDY_CLOUD_ENDPOINT,
 84→      publishableKey: env.WORKBUDDY_CLOUD_PUBLISHABLE_KEY,
 85→    });
 86→  } catch (err) {
 87→    logger.warn(
 88→      { err: err instanceof Error ? err.message : String(err) },
 89→      'WorkBuddy Cloud SDK initialization failed',
 90→    );
 91→    return null;
 92→  }
 93→  return {
 94→    name: 'workbuddy',
 95→    kind: 'workbuddy',
 96→    client: cloud,
 97→    models: [env.WORKBUDDY_CLOUD_MODEL],
 98→    minOutputTokens: 0,
 99→  };
100→}
101→
102→function resolveProvider(): Provider | null {
103→  // 1. WorkBuddy Cloud (keyless, uses WorkBuddy credits)
104→  if (env.LLM_PROVIDER === 'workbuddy' || (env.LLM_PROVIDER === 'auto' && env.WORKBUDDY_CLOUD_ENDPOINT)) {
105→    const wb = resolveWorkBuddyProvider();
106→    if (wb) return wb;
107→    // If explicitly requested but not configured, fall through to other providers
108→    if (env.LLM_PROVIDER === 'workbuddy') return null;
109→  }
110→
111→  // 2. Gemini
112→  if (env.GEMINI_API_KEY && env.LLM_PROVIDER !== 'tokenhub' && env.LLM_PROVIDER !== 'workbuddy') {
113→    return {
114→      name: 'gemini',
115→      kind: 'openai',
116→      client: new OpenAI({
117→        apiKey: env.GEMINI_API_KEY,
118→        baseURL: GEMINI_BASE_URL,
119→        timeout: env.LLM_TIMEOUT_MS,
120→        // One retry for "high demand" 503s and 429s, then the next model is tried
121→        maxRetries: 1,
122→      }),
123→      models: [env.GEMINI_MODEL, ...env.GEMINI_FALLBACK_MODELS.filter((m) => m !== env.GEMINI_MODEL)],
124→      minOutputTokens: GEMINI_MIN_OUTPUT_TOKENS,
125→      reasoningEffort: env.GEMINI_REASONING_EFFORT,
126→    };
127→  }
128→
129→  // 3. TokenHub
130→  if (env.LLM_PROVIDER === 'gemini' || env.LLM_PROVIDER === 'workbuddy') return null;
131→  const isSandbox = process.env.X_IDE_AUTH_PROXY !== undefined;
132→  const apiKey = env.TOKENHUB_API_KEY || (isSandbox ? 'mock_api_key' : '');
133→  if (!apiKey) return null;
134→  const useSandbox = isSandbox && apiKey === 'mock_api_key';
135→  return {
136→    name: 'tokenhub',
137→    kind: 'openai',
138→    client: new OpenAI({
139→      apiKey,
140→      baseURL: useSandbox ? 'http://tokenhub.openai.auth-proxy.local/v1' : env.TOKENHUB_BASE_URL,
141→      timeout: env.LLM_TIMEOUT_MS,
142→      maxRetries: 1,
143→    }),
144→    models: [env.TOKENHUB_MODEL],
145→    minOutputTokens: 0,
146→  };
147→}
148→
149→let provider: Provider | null | undefined;
150→
151→// A model that answered 429 (free-tier daily or per-minute quota) is skipped for a while
152→// so every later call does not spend a request finding out again.
153→const QUOTA_COOLDOWN_MS = 10 * 60_000;
154→const coolingUntil = new Map<string, number>();
155→
156→function getProvider(): Provider {
157→  if (provider === undefined) provider = resolveProvider();
158→  if (!provider) {
159→    throw new Error(
160→      'No LLM API key configured (set WORKBUDDY_CLOUD_* for WorkBuddy credits, '
161→      + 'GEMINI_API_KEY for Gemini, or TOKENHUB_API_KEY for TokenHub)',
162→    );
163→  }
164→  return provider;
165→}
166→
167→/** Which provider and models the agents will use; for health checks and logs. */
168→export function llmInfo(): { provider: string; models: string[] } | null {
169→  try {
170→    const p = getProvider();
171→    return { provider: p.name, models: p.models };
172→  } catch {
173→    return null;
174→  }
175→}
176→
177→/**
178→ * One streamed completion. Free-tier models can be slow but steady, so instead of
179→ * a single deadline the call is abandoned when no output arrives for
180→ * LLM_IDLE_TIMEOUT_MS, or when it runs longer than LLM_TIMEOUT_MS in total.
181→ *
182→ * Handles both the OpenAI SDK (signal in request options) and the WorkBuddy
183→ * Cloud SDK (signal inside the params object).
184→ */
185→async function streamCompletion(
186→  p: Provider,
187→  model: string,
188→  messages: ChatMessage[],
189→  options: ChatOptions
190→): Promise<string> {
191→  const controller = new AbortController();
192→  const total = setTimeout(() => controller.abort(new Error('total time limit reached')), env.LLM_TIMEOUT_MS);
193→  let idle: NodeJS.Timeout | undefined;
194→  const resetIdle = () => {
195→    clearTimeout(idle);
196→    idle = setTimeout(() => controller.abort(new Error('no output, model stalled')), env.LLM_IDLE_TIMEOUT_MS);
197→  };
198→
199→  try {
200→    resetIdle();
201→
202→    // eslint-disable-next-line @typescript-eslint/no-explicit-any
203→    let stream: AsyncIterable<any>;
204→
205→    if (p.kind === 'workbuddy') {
206→      // WorkBuddy Cloud SDK: signal goes inside the params object,
207→      // and stream:true is required (non-streaming is rejected by the API).
208→      stream = await p.client.llm.chat.completions.create({
209→        model,
210→        messages: messages as unknown as Record<string, string>[],
211→        temperature: options.temperature ?? 0.2,
212→        max_tokens: Math.max(options.max_tokens ?? 4096, p.minOutputTokens),
213→        stream: true,
214→        signal: controller.signal,
215→      });
216→    } else {
217→      // OpenAI SDK: signal is a separate request option.
218→      stream = await p.client.chat.completions.create(
219→        {
220→          model,
221→          messages: messages as OpenAI.Chat.ChatCompletionMessageParam[],
222→          temperature: options.temperature ?? 0.2,
223→          max_tokens: Math.max(options.max_tokens ?? 4096, p.minOutputTokens),
224→          ...(p.reasoningEffort ? { reasoning_effort: p.reasoningEffort } : {}),
225→          stream: true,
226→        },
227→        { signal: controller.signal },
228→      );
229→    }
230→
231→    let content = '';
232→    let finishReason: string | null = null;
233→    // eslint-disable-next-line @typescript-eslint/no-explicit-any
234→    for await (const chunk of stream as AsyncIterable<any>) {
235→      resetIdle();
236→      const choice = chunk.choices?.[0];
237→      content += choice?.delta?.content ?? '';
238→      finishReason = choice?.finish_reason ?? finishReason;
239→    }
240→    if (finishReason === 'length') throw new Error(`${model} hit the output token limit before finishing`);
241→    if (!content) throw new Error(`${model} returned an empty response`);
242→    return content;
243→  } catch (err) {
244→    // Report why we aborted rather than the SDK's generic "Request was aborted"
245→    if (controller.signal.aborted) throw new Error(`${model}: ${String(controller.signal.reason?.message)}`);
246→    throw err;
247→  } finally {
248→    clearTimeout(total);
249→    clearTimeout(idle);
250→  }
251→}
252→
253→/**
254→ * Chat completion. Returns the assistant's text content.
255→ * Tries each configured model in turn; throws the last error if all fail.
256→ */
257→export async function chatCompletion(
258→  messages: ChatMessage[],
259→  options: ChatOptions = {}
260→): Promise<string> {
261→  const p = getProvider();
262→  let lastError: unknown;
263→
264→  const now = Date.now();
265→  const available = p.models.filter((m) => (coolingUntil.get(m) ?? 0) <= now);
266→  // If every model is cooling down, try them all anyway rather than fail outright
267→  for (const model of available.length ? available : p.models) {
268→    try {
269→      return await streamCompletion(p, model, messages, options);
270→    } catch (err) {
271→      lastError = err;
272→      // OpenAI SDK: 429 → cooldown
273→      if (err instanceof OpenAI.APIError && err.status === 429) {
274→        coolingUntil.set(model, Date.now() + QUOTA_COOLDOWN_MS);
275→      }
276→      // WorkBuddy Cloud SDK: quota_* error codes → cooldown
277→      const wbErr = err as { error?: { code?: string } };
278→      if (wbErr?.error?.code?.startsWith('quota_') && wbErr.error.code !== 'quota_rate_limited') {
279→        coolingUntil.set(model, Date.now() + QUOTA_COOLDOWN_MS);
280→      }
281→      logger.warn(
282→        { provider: p.name, model, err: err instanceof Error ? err.message : String(err) },
283→        'LLM call failed; trying the next model if any',
284→      );
285→    }
286→  }
287→  throw lastError;
288→}
