  1→/**
  2→ * DatasetImport — turn a sample dataset (e.g. DISP-002, DISP-003) into a case.
  3→ * Accepts the .json file or the sample .md (the JSON block is extracted).
  4→ */
  5→
  6→import { useRef } from 'react';
  7→import { useNavigate } from 'react-router-dom';
  8→import { useMutation, useQueryClient } from '@tanstack/react-query';
  9→import { toast } from 'sonner';
 10→import { Database, Loader2, Upload } from 'lucide-react';
 11→import { Button } from '@/components/ui/button';
 12→import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
 13→import { disputeApi } from '@/lib/dispute-api';
 14→import { getErrorMessage } from '@/lib/api-client';
 15→
 16→const SAMPLES = [
 17→  { file: 'disp-002.json', label: 'Load sample DISP-002 (no-show charge)' },
 18→  { file: 'disp-003.json', label: 'Load sample DISP-003 (route deviation)' },
 19→];
 20→
 21→function extractJson(text: string): unknown {
 22→  const block = text.match(/```json\s*([\s\S]*?)```/i);
 23→  return JSON.parse(block ? block[1] : text);
 24→}
 25→
 26→export function DatasetImport() {
 27→  const navigate = useNavigate();
 28→  const queryClient = useQueryClient();
 29→  const fileInput = useRef<HTMLInputElement>(null);
 30→
 31→  const importMutation = useMutation({
 32→    mutationFn: disputeApi.importDataset,
 33→    onSuccess: ({ case: c, existing }) => {
 34→      queryClient.invalidateQueries({ queryKey: ['disputes'] });
 35→      queryClient.invalidateQueries({ queryKey: ['dispute-stats'] });
 36→      if (existing) toast.info(`${c.caseNumber} was already imported. Opening the existing case.`);
 37→      else toast.success(`Imported ${c.caseNumber}`);
 38→      navigate(`/cases/${c.id}`);
 39→    },
 40→    onError: (error) => toast.error(getErrorMessage(error)),
 41→  });
 42→
 43→  async function loadSample(file: string) {
 44→    try {
 45→      const res = await fetch(`/samples/${file}`);
 46→      importMutation.mutate(await res.json());
 47→    } catch {
 48→      toast.error('Could not load the sample dataset.');
 49→    }
 50→  }
 51→
 52→  async function handleFile(e: React.ChangeEvent<HTMLInputElement>) {
 53→    const file = e.target.files?.[0];
 54→    if (!file) return;
 55→    try {
 56→      importMutation.mutate(extractJson(await file.text()));
 57→    } catch {
 58→      toast.error('The file is not a valid JSON dataset.');
 59→    }
 60→    if (fileInput.current) fileInput.current.value = '';
 61→  }
 62→
 63→  return (
 64→    <Card className="mb-5">
 65→      <CardHeader className="pb-3">
 66→        <CardTitle className="text-base flex items-center gap-2">
 67→          <Database className="w-4 h-4" />
 68→          Import dataset
 69→        </CardTitle>
 70→      </CardHeader>
 71→      <CardContent className="space-y-3">
 72→        <p className="text-sm text-muted-foreground">
 73→          Create a case directly from a dataset containing GPS, chat, app events, fare, and policy data.
 74→          Supported dispute types: no-show charge and route deviation.
 75→        </p>
 76→        <div className="flex flex-wrap items-center gap-3">
 77→          {SAMPLES.map((sample) => (
 78→            <Button
 79→              key={sample.file}
 80→              type="button"
 81→              onClick={() => loadSample(sample.file)}
 82→              disabled={importMutation.isPending}
 83→            >
 84→              {importMutation.isPending ? (
 85→                <Loader2 className="w-4 h-4 mr-1.5 animate-spin" />
 86→              ) : (
 87→                <Database className="w-4 h-4 mr-1.5" />
 88→              )}
 89→              {sample.label}
 90→            </Button>
 91→          ))}
 92→          <Button
 93→            type="button"
 94→            variant="outline"
 95→            disabled={importMutation.isPending}
 96→            onClick={() => fileInput.current?.click()}
 97→          >
 98→            <Upload className="w-4 h-4 mr-1.5" />
 99→            Choose dataset file (.json / .md)
100→          </Button>
101→          <input
102→            ref={fileInput}
103→            type="file"
104→            accept=".json,.md,.txt"
105→            className="hidden"
106→            onChange={handleFile}
107→          />
108→        </div>
109→      </CardContent>
110→    </Card>
111→  );
112→}
113→

