  1→/**
  2→ * Dashboard — Dispute case overview with stats and case list
  3→ */
  4→
  5→import { useMemo, useState } from 'react';
  6→import { useQuery } from '@tanstack/react-query';
  7→import { Link, useNavigate } from 'react-router-dom';
  8→import {
  9→  Loader2,
 10→  ArrowRight,
 11→  ArrowDown,
 12→  ArrowUp,
 13→  ChevronsUpDown,
 14→  FilePlus,
 15→} from 'lucide-react';
 16→import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
 17→import { Badge } from '@/components/ui/badge';
 18→import { Button } from '@/components/ui/button';
 19→import {
 20→  Table,
 21→  TableBody,
 22→  TableCell,
 23→  TableHead,
 24→  TableHeader,
 25→  TableRow,
 26→} from '@/components/ui/table';
 27→import { disputeApi } from '@/lib/dispute-api';
 28→import {
 29→  typeLabels,
 30→  priorityLabels,
 31→  statusLabels,
 32→  statusBadgeClass,
 33→  priorityBadgeClass,
 34→  formatDateTime,
 35→} from '@/lib/dispute-utils';
 36→import { cn } from '@/lib/utils';
 37→import type { DisputeCase } from '@/types/dispute';
 38→
 39→type SortKey = 'caseNumber' | 'title' | 'createdAt' | 'type' | 'priority' | 'status';
 40→type SortDir = 'asc' | 'desc';
 41→interface SortState {
 42→  key: SortKey | null;
 43→  dir: SortDir;
 44→}
 45→
 46→const priorityRank: Record<DisputeCase['priority'], number> = { low: 0, medium: 1, high: 2, urgent: 3 };
 47→const statusRank: Record<DisputeCase['status'], number> = { pending: 0, under_review: 1, resolved: 2 };
 48→
 49→/** Natural, case-insensitive text comparison ("DR-2024-002" < "DR-2024-010"). */
 50→const compareText = (a: string, b: string) =>
 51→  a.localeCompare(b, 'en', { numeric: true, sensitivity: 'base' });
 52→
 53→/** Titles sort by their first letter, ignoring leading symbols such as "[DISP-003]". */
 54→const titleKey = (title: string) => title.replace(/^[^A-Za-z0-9]+/, '');
 55→
 56→function compareBy(a: DisputeCase, b: DisputeCase, key: SortKey): number {
 57→  switch (key) {
 58→    case 'caseNumber':
 59→      return compareText(a.caseNumber, b.caseNumber);
 60→    case 'title':
 61→      return compareText(titleKey(a.title), titleKey(b.title));
 62→    case 'createdAt':
 63→      return (Date.parse(a.createdAt) || 0) - (Date.parse(b.createdAt) || 0);
 64→    case 'type':
 65→      return compareText(typeLabels[a.type], typeLabels[b.type]);
 66→    case 'priority':
 67→      return priorityRank[a.priority] - priorityRank[b.priority];
 68→    case 'status':
 69→      return statusRank[a.status] - statusRank[b.status];
 70→  }
 71→}
 72→
 73→function SortHead({
 74→  label,
 75→  sortKey,
 76→  sort,
 77→  onSort,
 78→  className,
 79→}: {
 80→  label: string;
 81→  sortKey: SortKey;
 82→  sort: SortState;
 83→  onSort: (key: SortKey) => void;
 84→  className?: string;
 85→}) {
 86→  const active = sort.key === sortKey;
 87→  const Icon = !active ? ChevronsUpDown : sort.dir === 'asc' ? ArrowUp : ArrowDown;
 88→  return (
 89→    <TableHead
 90→      className={className}
 91→      aria-sort={active ? (sort.dir === 'asc' ? 'ascending' : 'descending') : 'none'}
 92→    >
 93→      <button
 94→        type="button"
 95→        onClick={() => onSort(sortKey)}
 96→        className={cn(
 97→          'inline-flex items-center gap-1 rounded -ml-1 px-1 py-0.5 hover:text-foreground',
 98→          active ? 'text-foreground' : 'text-muted-foreground'
 99→        )}
100→        title={`Sort by ${label.toLowerCase()}`}
101→      >
102→        {label}
103→        <Icon className={cn('w-3.5 h-3.5', !active && 'opacity-40')} />
104→      </button>
105→    </TableHead>
106→  );
107→}
108→
109→export default function Dashboard() {
110→  const navigate = useNavigate();
111→  const { data: stats } = useQuery({
112→    queryKey: ['dispute-stats'],
113→    queryFn: disputeApi.getStats,
114→  });
115→
116→  const { data: cases, isLoading } = useQuery({
117→    queryKey: ['disputes'],
118→    queryFn: disputeApi.getAll,
119→  });
120→
121→  // First click on a column sorts descending, the second ascending, then it toggles.
122→  // No column is active at first; the list then shows the newest cases on top.
123→  const [sort, setSort] = useState<SortState>({ key: null, dir: 'desc' });
124→  const handleSort = (key: SortKey) =>
125→    setSort((prev) =>
126→      prev.key === key ? { key, dir: prev.dir === 'desc' ? 'asc' : 'desc' } : { key, dir: 'desc' }
127→    );
128→  const sortedCases = useMemo(() => {
129→    if (!cases) return cases;
130→    if (!sort.key) {
131→      return [...cases].sort((a, b) => (Date.parse(b.createdAt) || 0) - (Date.parse(a.createdAt) || 0));
132→    }
133→    const key = sort.key;
134→    const sign = sort.dir === 'asc' ? 1 : -1;
135→    return [...cases].sort(
136→      (a, b) =>
137→        sign * compareBy(a, b, key) ||
138→        (Date.parse(b.createdAt) || 0) - (Date.parse(a.createdAt) || 0) ||
139→        compareText(a.caseNumber, b.caseNumber)
140→    );
141→  }, [cases, sort]);
142→
143→  // The most urgent case still waiting for a decision
144→  const nextCase = useMemo(() => {
145→    const open = (cases ?? []).filter((c) => c.status !== 'resolved');
146→    return [...open].sort(
147→      (a, b) =>
148→        priorityRank[b.priority] - priorityRank[a.priority] ||
149→        (Date.parse(a.createdAt) || 0) - (Date.parse(b.createdAt) || 0)
150→    )[0];
151→  }, [cases]);
152→
153→  return (
154→    <div className="p-6 lg:p-8 max-w-6xl mx-auto">
155→      {/* Hero: the queue at a glance and the one thing to do next */}
156→      <section className="relative mb-6 overflow-hidden rounded-2xl bg-gradient-to-br from-[#ee4a72] via-[#e93864] to-[#b8264f] px-5 py-6 md:px-8 md:py-8 text-white shadow-md">
157→        <div className="pointer-events-none absolute -right-16 -top-24 h-72 w-72 rounded-full bg-white/15 blur-3xl" />
158→        <div className="pointer-events-none absolute -bottom-32 left-1/3 h-64 w-64 rounded-full bg-[#7a1633]/30 blur-3xl" />
159→        <div className="relative grid gap-8 lg:grid-cols-[1fr_auto] lg:items-center">
160→          <div>
161→            <h1 className="text-3xl md:text-4xl font-extrabold leading-tight">
162→              {stats === undefined
163→                ? 'Loading queue…'
164→                : stats.pending > 0
165→                  ? `${stats.pending} ${stats.pending === 1 ? 'case is' : 'cases are'} waiting for review`
166→                  : 'The queue is clear'}
167→            </h1>
168→            <div className="mt-6 flex flex-wrap gap-3">
169→              {nextCase && (
170→                <Link to={`/cases/${nextCase.id}`}>
171→                  <Button size="lg" className="bg-white text-primary hover:bg-white/90">
172→                    Open most urgent case
173→                    <ArrowRight className="ml-2 h-4 w-4" />
174→                  </Button>
175→                </Link>
176→              )}
177→              <Link to="/submit">
178→                <Button size="lg" variant="outline" className="border-white/40 bg-transparent text-white hover:bg-white/15 hover:text-white">
179→                  <FilePlus className="mr-2 h-4 w-4" />
180→                  Submit new case
181→                </Button>
182→              </Link>
183→            </div>
184→          </div>
185→          <div className="grid grid-cols-3 gap-3 lg:w-96">
186→            {[
187→              { label: 'Total', value: stats?.total },
188→              { label: 'Under review', value: stats?.underReview },
189→              { label: 'Resolved', value: stats?.resolved },
190→            ].map((t) => (
191→              <div key={t.label} className="rounded-xl bg-white/15 px-4 py-4 ring-1 ring-white/20">
192→                <div className="text-3xl font-extrabold">{t.value ?? '--'}</div>
193→                <div className="mt-1 text-xs text-white/65">{t.label}</div>
194→              </div>
195→            ))}
196→          </div>
197→        </div>
198→      </section>
199→
200→      {/* Case List */}
201→      <Card>
202→        <CardHeader>
203→          <div className="flex items-center justify-between gap-3">
204→            <CardTitle className="text-lg">Dispute cases</CardTitle>
205→          </div>
206→        </CardHeader>
207→        <CardContent>
208→          {isLoading ? (
209→            <div className="flex items-center justify-center py-12">
210→              <Loader2 className="w-6 h-6 animate-spin text-muted-foreground" />
211→            </div>
212→          ) : (
213→            <Table>
214→              <TableHeader>
215→                <TableRow>
216→                  <SortHead label="Case number" sortKey="caseNumber" sort={sort} onSort={handleSort} />
217→                  <SortHead label="Title" sortKey="title" sort={sort} onSort={handleSort} className="w-full" />
218→                  <SortHead label="Created" sortKey="createdAt" sort={sort} onSort={handleSort} className="hidden lg:table-cell" />
219→                  <SortHead label="Type" sortKey="type" sort={sort} onSort={handleSort} className="hidden xl:table-cell" />
220→                  <SortHead label="Priority" sortKey="priority" sort={sort} onSort={handleSort} />
221→                  <SortHead label="Status" sortKey="status" sort={sort} onSort={handleSort} />
222→                  <TableHead className="text-right">Action</TableHead>
223→                </TableRow>
224→              </TableHeader>
225→              <TableBody>
226→                {sortedCases?.map((c) => (
227→                  <TableRow key={c.id} className="cursor-pointer hover:bg-accent/40" onClick={() => navigate(`/cases/${c.id}`)}>
228→                    <TableCell className="font-mono text-sm text-muted-foreground">
229→                      {c.caseNumber}
230→                    </TableCell>
231→                    <TableCell className="w-full max-w-0 font-medium">
232→                      <span className="block min-w-40 truncate" title={c.title}>{c.title}</span>
233→                    </TableCell>
234→                    <TableCell className="hidden lg:table-cell text-sm text-muted-foreground">
235→                      {formatDateTime(c.createdAt)}
236→                    </TableCell>
237→                    <TableCell className="hidden xl:table-cell">
238→                      <Badge variant="outline">{typeLabels[c.type]}</Badge>
239→                    </TableCell>
240→                    <TableCell>
241→                      <Badge
242→                        variant="outline"
243→                        className={priorityBadgeClass(c.priority)}
244→                      >
245→                        {priorityLabels[c.priority]}
246→                      </Badge>
247→                    </TableCell>
248→                    <TableCell>
249→                      <Badge
250→                        variant="outline"
251→                        className={statusBadgeClass(c.status)}
252→                      >
253→                        {statusLabels[c.status]}
254→                      </Badge>
255→                      {c.escalation?.needsHuman && (
256→                        <Badge
257→                          variant="outline"
258→                          className="ml-1.5 border-amber-300 bg-amber-50 text-amber-700"
259→                        >
260→                          Human review
261→                        </Badge>
262→                      )}
263→                    </TableCell>
264→                    <TableCell className="text-right">
265→                      <Link to={`/cases/${c.id}`}>
266→                        <Button variant="ghost" size="sm">
267→                          View details
268→                          <ArrowRight className="w-3.5 h-3.5 ml-1" />
269→                        </Button>
270→                      </Link>
271→                    </TableCell>
272→                  </TableRow>
273→                ))}
274→              </TableBody>
275→            </Table>
276→          )}
277→        </CardContent>
278→      </Card>
279→    </div>
280→  );
281→}
