188→function generateId(): string {
189→  counter++;
190→  return `case-${String(counter).padStart(3, '0')}`;
191→}
192→
193→function generateCaseNumber(): string {
194→  const year = new Date().getFullYear();
195→  const num = String(cases.length + 1).padStart(3, '0');
196→  return `DR-${year}-${num}`;
197→}
198→
199→export const disputeStore = {
200→  getAll(): DisputeCase[] {
201→    const priorityRank = { urgent: 4, high: 3, medium: 2, low: 1 };
202→    return [...cases].sort(
203→      (a, b) =>
204→        priorityRank[b.priority] - priorityRank[a.priority] ||
205→        new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
206→    );
207→  },
208→
209→  getById(id: string): DisputeCase | undefined {
210→    return cases.find((c) => c.id === id);
211→  },
212→
213→  create(
214→    dto: CreateDisputeDTO,
215→    opts: { caseNumber?: string; dataset?: SampleDataset; createdAt?: string } = {}
216→  ): DisputeCase {
217→    const now = new Date().toISOString();
218→    const newCase: DisputeCase = {
219→      id: generateId(),
220→      caseNumber: opts.caseNumber ?? generateCaseNumber(),
221→      status: 'pending',
222→      priority: dto.priority,
223→      type: dto.type,
224→      title: dto.title,
225→      createdAt: opts.createdAt ?? now,
226→      updatedAt: now,
227→      driver: dto.driver,
228→      passenger: dto.passenger,
229→      trip: dto.trip,
230→      evidence: dto.evidence.map((e) => makeEvidence(e)),
231→      dataset: opts.dataset,
232→    };
233→    cases.push(newCase);
234→    return newCase;
235→  },
236→
237→  addEvidence(id: string, input: NewEvidence): DisputeCase | undefined {
238→    const c = cases.find((c) => c.id === id);
239→    if (!c) return undefined;
240→    c.evidence.push(makeEvidence(input));
241→    c.updatedAt = new Date().toISOString();
242→    return c;
243→  },
244→
245→  updateReview(id: string, review: DisputeCase['review']): DisputeCase | undefined {
246→    const c = cases.find((c) => c.id === id);
247→    if (!c || !review) return undefined;
248→    c.review = review;
249→    if (review.priorityAssessment) {
250→      c.priorityAssessment = review.priorityAssessment;
251→      c.priority = review.priorityAssessment.priority;
252→    }
253→    // A human decision stands: retain the new AI result for reference without
254→    // reopening the case or discarding either feedback mechanism.
255→    if (c.humanOverride) {
256→      c.status = 'resolved';
257→      c.updatedAt = new Date().toISOString();
258→      return c;
259→    }
260→    c.learningFeedback = undefined;
261→    const failed = review.mode === 'fallback';
262→    if (failed) {
263→      // Review could not run: stay open for a retry, nothing to escalate
264→      c.escalation = review.escalation ?? {
265→        needsHuman: false,
266→        reason: 'AI review did not complete. Retry the review.',
267→      };
268→      c.status = 'pending';
269→    } else if (review.escalation?.needsHuman) {
270→      c.escalation = review.escalation;
271→      c.status = 'under_review';
272→    } else {
273→      c.escalation = review.escalation ?? { needsHuman: false, reason: '' };
274→      c.status = 'resolved';
275→    }
276→    c.updatedAt = new Date().toISOString();
277→    return c;
278→  },
279→
280→  /** A human reviewer's decision; closes the case and records it for later learning. */
281→  override(
282→    id: string,
283→    decision: {
284→      recommendation: Recommendation;
285→      reason: string;
286→      decidedBy?: string;
287→      useAsPrecedent: boolean;
288→    }
289→  ): DisputeCase | undefined {
290→    const c = cases.find((c) => c.id === id);
291→    if (!c) return undefined;
292→    const now = new Date().toISOString();
293→    c.humanOverride = { ...decision, decidedAt: now };
294→    c.escalation = { needsHuman: false, reason: 'Resolved by a human reviewer.' };
295→    c.status = 'resolved';
296→    c.updatedAt = now;
297→    if (decision.useAsPrecedent) precedentStore.upsert(precedentFromCase(c, c.humanOverride));
298→    else precedentStore.remove(c.caseNumber);
299→    return c;
300→  },
301→
302→  /** Withdraws a human decision and restores the status implied by the AI result. */
303→  clearOverride(id: string): DisputeCase | undefined {
304→    const c = cases.find((item) => item.id === id);
305→    if (!c) return undefined;
306→    if (!c.humanOverride) return c;
307→    c.humanOverride = undefined;
308→    c.learningFeedback = undefined;
309→    precedentStore.remove(c.caseNumber);
310→    if (c.review) return this.updateReview(id, c.review);
311→    c.escalation = undefined;
312→    c.status = 'pending';
313→    c.updatedAt = new Date().toISOString();
314→    return c;
315→  },
316→
317→  /** A deleted precedent remains a decision, but no longer teaches the Judge. */
318→  unmarkPrecedent(caseNumber: string): void {
319→    const c = cases.find((item) => item.caseNumber === caseNumber);
320→    if (c?.humanOverride) c.humanOverride.useAsPrecedent = false;
321→  },
322→
323→  setPriorityAssessment(id: string, assessment: PriorityAssessment): DisputeCase | undefined {
324→    const c = cases.find((item) => item.id === id);
325→    if (!c) return undefined;
326→    c.priorityAssessment = assessment;
327→    c.priority = assessment.priority;
328→    c.updatedAt = new Date().toISOString();
329→    return c;
330→  },
331→
332→  setLearningFeedback(id: string, feedback: LearningFeedback): DisputeCase | undefined {
333→    const c = cases.find((item) => item.id === id);
334→    if (!c) return undefined;
335→    c.learningFeedback = feedback;
336→    c.updatedAt = new Date().toISOString();
337→    return c;
338→  },
339→
340→  setStatus(id: string, status: DisputeCase['status']): DisputeCase | undefined {
341→    const c = cases.find((c) => c.id === id);
342→    if (!c) return undefined;
343→    c.status = status;
344→    c.updatedAt = new Date().toISOString();
345→    return c;
346→  },
347→
348→  getStats(): DashboardStats {
349→    const stats: DashboardStats = {
350→      total: cases.length,
351→      pending: 0,
352→      underReview: 0,
353→      resolved: 0,
354→      byType: {},
355→      byPriority: {},
356→    };
357→    for (const c of cases) {
358→      if (c.status === 'pending') stats.pending++;
359→      else if (c.status === 'under_review') stats.underReview++;
360→      else if (c.status === 'resolved') stats.resolved++;
361→      stats.byType[c.type] = (stats.byType[c.type] || 0) + 1;
362→      stats.byPriority[c.priority] = (stats.byPriority[c.priority] || 0) + 1;
363→    }
364→    return stats;
365→  },
366→};
