 13→import type { CreateDisputeDTO, NewEvidence, TripInfo } from './types';
 14→
 15→function clock(timestamp: string): string {
 16→  return timestamp.replace('T', ' ').replace(/(\.\d+)?(Z|[+-]\d\d:\d\d)$/, ' $2').trim();
 17→}
 18→
 19→export function datasetToCreateDTO(data: SampleDataset): CreateDisputeDTO {
 20→  const t = data.dispute_ticket;
