35→} from '@/lib/dispute-utils';
36→import { cn } from '@/lib/utils';
37→import type { DisputeCase } from '@/types/dispute';
38→
39→type SortKey = 'caseNumber' | 'title' | 'createdAt' | 'type' | 'priority' | 'status';
40→type SortDir = 'asc' | 'desc';
41→interface SortState {
42→  key: SortKey | null;
43→  dir: SortDir;
44→}
45→
46→const priorityRank: Record<DisputeCase['priority'], number> = { low: 0, medium: 1, high: 2, urgent: 3 };
47→const statusRank: Record<DisputeCase['status'], number> = { pending: 0, under_review: 1, resolved: 2 };
48→
49→/** Natural, case-insensitive text comparison ("DR-2024-002" < "DR-2024-010"). */
50→const compareText = (a: string, b: string) =>
51→  a.localeCompare(b, 'en', { numeric: true, sensitivity: 'base' });
52→
53→/** Titles sort by their first letter, ignoring leading symbols such as "[DISP-003]". */
54→const titleKey = (title: string) => title.replace(/^[^A-Za-z0-9]+/, '');
55→
56→function compareBy(a: DisputeCase, b: DisputeCase, key: SortKey): number {
57→  switch (key) {
58→    case 'caseNumber':
59→      return compareText(a.caseNumber, b.caseNumber);
60→    case 'title':
61→      return compareText(titleKey(a.title), titleKey(b.title));
62→    case 'createdAt':
