  1→/**
  2→ * Dispute Review — turn a sample dataset (e.g. DISP-002, DISP-003) into a dashboard case.
  3→ */
  4→
  5→import {
  6→  isFareDisputeDataset,
  7→  isLegacyRouteDeviationDataset,
  8→  isNoShowDataset,
  9→  type SampleDataset,
 10→} from './agents/dataset';
 11→import { analyzeRoute } from './agents/route-analysis';
 12→import { RYDE_POLICY_V2_1 } from './agents/policy';
 13→import type { CreateDisputeDTO, NewEvidence, TripInfo } from './types';
 14→
 15→function clock(timestamp: string): string {
 16→  return timestamp.replace('T', ' ').replace(/(\.\d+)?(Z|[+-]\d\d:\d\d)$/, ' $2').trim();
 17→}
 18→
 19→export function datasetToCreateDTO(data: SampleDataset): CreateDisputeDTO {
 20→  const t = data.dispute_ticket;
 21→
 22→  const chatLines = (sender: 'rider' | 'driver' | 'system') =>
 23→    data.chat_logs
 24→      .filter((m) => m.sender === sender)
 25→      .map((m) => `[${clock(m.timestamp)}] (${m.type}) ${m.content}`)
 26→      .join('\n');
 27→
 28→  const evidence: NewEvidence[] = [];
 29→  const add = (e: NewEvidence) => {
 30→    if (e.content.trim()) evidence.push(e);
 31→  };
 32→
 33→  add({ party: 'rider', kind: 'chat', title: 'Rider chat and call log', content: chatLines('rider') });
 34→  add({ party: 'driver', kind: 'chat', title: 'Driver chat and call log', content: chatLines('driver') });
 35→  add({ party: 'platform', kind: 'chat', title: 'System notifications', content: chatLines('system') });
 36→  add({
 37→    party: 'platform',
 38→    kind: 'gps',
 39→    title: `GPS trace (${data.gps_telemetry.length} points)`,
 40→    content: data.gps_telemetry
 41→      .map((p) => `[${clock(p.timestamp)}] ${p.lat}, ${p.lng} | ${p.speed_kmh} km/h | ${p.status}`)
 42→      .join('\n'),
 43→  });
 44→  add({
 45→    party: 'platform',
 46→    kind: 'text',
 47→    title: 'App event log',
 48→    content: data.app_events
 49→      .map((e) => `[${clock(e.timestamp)}] ${e.event_type}: ${e.details}`)
 50→      .join('\n'),
 51→  });
 52→
 53→  // "Honda HR-V (SGP 4521 M)" -> model + plate
 54→  const vehicle = data.driver_profile.vehicle;
 55→  const plateMatch = vehicle.match(/\(([^)]+)\)\s*$/);
 56→  const car = {
 57→    vehicleModel: plateMatch ? vehicle.replace(plateMatch[0], '').trim() : vehicle,
 58→    plateNumber: plateMatch ? plateMatch[1] : '',
 59→    currency: 'SGD' as const,
 60→  };
 61→  let trip: TripInfo;
 62→
 63→  if (isNoShowDataset(data)) {
 64→    add({
 65→      party: 'platform',
 66→      kind: 'text',
 67→      title: 'Ryde Dispute Resolution Policy v2.1 — no-show',
 68→      content:
 69→        `Wait from scheduled pickup: ${RYDE_POLICY_V2_1.no_show.free_wait_time_min} minutes; ` +
 70→        `fee: SGD ${RYDE_POLICY_V2_1.no_show.cancellation_fee.toFixed(2)} paid to the driver; ` +
 71→        `required contact: at least one in-app message and one in-app call.`,
 72→    });
 73→    const td = data.trip_data;
 74→    trip = {
 75→      pickupLocation: td.pickup_location.name,
 76→      dropoffLocation: td.dropoff_location.name,
 77→      pickupTime: td.scheduled_time,
 78→      dropoffTime: td.cancellation_time,
 79→      fare: td.cancellation_fee,
 80→      distance: 0,
 81→      ...car,
 82→    };
 83→  } else if (isFareDisputeDataset(data)) {
 84→    const td = data.trip_data;
 85→    const comparison = data.fare_breakdown.comparison;
 86→    add({
 87→      party: 'platform', kind: 'payment', title: 'Fare and surge comparison',
 88→      content:
 89→        `Upfront quote: SGD ${td.upfront_quote.toFixed(2)}; actual fare: SGD ${td.actual_fare.toFixed(2)}; ` +
 90→        `difference: SGD ${td.fare_difference.toFixed(2)}. ` +
 91→        `Surge ${data.surge_pricing_log.quote_time_surge}x → ${data.surge_pricing_log.trip_start_surge}x; ` +
 92→        `rider notified: ${data.surge_pricing_log.rider_notified}; root cause: ${comparison.root_cause}.`,
 93→    });
 94→    add({
 95→      party: 'platform', kind: 'text', title: 'Ryde Dispute Resolution Policy v2.1',
 96→      content:
 97→        `An unnotified surge increase requires refund of actual fare minus upfront quote. ` +
 98→        `Surge-exempt components: ${RYDE_POLICY_V2_1.fare_and_surge.surge_exempt_components.join(', ')}.`,
 99→    });
100→    trip = {
101→      pickupLocation: td.pickup_location.name,
102→      dropoffLocation: td.dropoff_location.name,
103→      pickupTime: td.start_time,
104→      dropoffTime: td.end_time,
105→      fare: td.actual_fare,
106→      distance: 0,
107→      ...car,
108→    };
109→  } else if (isLegacyRouteDeviationDataset(data)) {
110→    const td = data.trip_data;
111→    const fb = td.fare_breakdown;
112→    const route = data.recommended_route;
113→    add({
114→      party: 'platform',
115→      kind: 'payment',
116→      title: 'Fare breakdown',
117→      content:
118→        `Upfront estimate: ${td.estimated_fare.toFixed(2)}; charged: ${td.final_fare.toFixed(2)}\n` +
119→        `Base ${fb.base_fare.toFixed(2)} + distance ${fb.distance_fare.toFixed(2)} + time ${fb.time_fare.toFixed(2)}, ` +
120→        `surge x${fb.surge_multiplier}, booking fee ${fb.booking_fee.toFixed(2)}, ` +
121→        `promo ${fb.promo_code ?? 'none'} (-${fb.promo_discount.toFixed(2)}) = ${fb.total.toFixed(2)}`,
122→    });
123→    add({
124→      party: 'platform',
125→      kind: 'gps',
126→      title: `Recommended route (${route.summary})`,
127→      content:
128→        `${route.distance_km} km, ${route.duration_min} min\n` +
129→        route.waypoints.map((w) => `${w.lat}, ${w.lng}${w.name ? ` | ${w.name}` : ''}`).join('\n'),
130→    });
131→    add({
132→      party: 'platform',
133→      kind: 'text',
134→      title: 'Route analysis (computed from GPS and fare records)',
135→      content: analyzeRoute(data).findings.join('\n'),
136→    });
137→    const p = data.fare_policy;
138→    add({
139→      party: 'platform',
140→      kind: 'text',
141→      title: 'Fare policy',
142→      content:
143→        `Deviation tolerance: ${p.deviation_tolerance_pct}%; refund basis: ${p.refund_basis}; ` +
144→        `exemptions: ${p.exempt_reasons.join(', ')}`,
145→    });
146→    trip = {
147→      pickupLocation: td.pickup_location.name,
148→      dropoffLocation: td.dropoff_location.name,
149→      pickupTime: td.pickup_time,
150→      dropoffTime: td.dropoff_time,
151→      fare: td.final_fare,
152→      distance: td.actual_distance_km,
153→      ...car,
154→    };
155→  } else {
156→    const td = data.trip_data;
157→    const fb = data.fare_breakdown;
158→    const route = data.optimal_route;
159→    add({
160→      party: 'platform', kind: 'payment', title: 'Fare breakdown',
161→      content:
162→        `Estimated fare: SGD ${td.estimated_fare.toFixed(2)}; actual fare: SGD ${td.actual_fare.toFixed(2)}; ` +
163→        `excess: SGD ${td.excess_fare.toFixed(2)}; excess distance fare: SGD ${fb.excess_distance_fare.toFixed(2)}; ` +
164→        `excess tolls: SGD ${fb.excess_tolls.toFixed(2)}.`,
165→    });
166→    add({
167→      party: 'platform', kind: 'gps', title: `Recommended route (${route.route_name})`,
168→      content:
169→        `${route.estimated_distance_km} km, ${route.estimated_duration_min} min\n` +
170→        route.waypoints.map((waypoint) =>
171→          `${waypoint.lat}, ${waypoint.lng}${typeof waypoint.location_desc === 'string' ? ` | ${waypoint.location_desc}` : ''}`
172→        ).join('\n'),
173→    });
174→    add({
175→      party: 'platform', kind: 'text', title: 'Traffic evidence',
176→      content: JSON.stringify({ conditions: data.traffic_conditions, analysis: data.traffic_analysis }),
177→    });
178→    add({
179→      party: 'platform', kind: 'text', title: 'Route analysis (computed from GPS and fare records)',
180→      content: analyzeRoute(data).findings.join('\n'),
181→    });
182→    add({
183→      party: 'platform', kind: 'text', title: 'Ryde Dispute Resolution Policy v2.1',
184→      content:
185→        `Driver notice is required before or at deviation. Distance tolerance: ` +
186→        `${RYDE_POLICY_V2_1.route_deviation.distance_tolerance_km} km; ` +
187→        `human review above ${RYDE_POLICY_V2_1.route_deviation.human_review_above_km} km.`,
188→    });
189→    trip = {
190→      pickupLocation: td.pickup_location.name,
191→      dropoffLocation: td.dropoff_location.name,
192→      pickupTime: td.start_time,
193→      dropoffTime: td.end_time,
194→      fare: td.actual_fare,
195→      distance: td.actual_distance_km,
196→      ...car,
197→    };
198→  }
199→
200→  return {
201→    title: `[${t.dispute_id}] ${t.description}`.slice(0, 90),
202→    priority: 'medium',
203→    type: t.dispute_type,
204→    driver: {
205→      name: data.driver_profile.name,
206→      id: data.driver_profile.driver_id,
207→      rating: data.driver_profile.avg_rating,
208→      statement: '(The dataset does not include a separate driver statement.)',
209→    },
210→    passenger: {
211→      name: data.rider_profile.name,
212→      id: data.rider_profile.rider_id,
213→      rating: data.rider_profile.avg_rating,
214→      statement: t.filed_by === 'rider' ? t.description : '',
215→    },
216→    trip,
217→    evidence,
218→  };
219→}
